import{_ as e,o as t,c as o,aO as r}from"./chunks/framework.vjUPZZJn.js";const m=JSON.parse('{"title":"SumatraPDF 反向搜索配置：从 PDF 双击跳回编辑器源码","description":"","frontmatter":{"date":"2026-11-17T04:30:00.000Z","title":"SumatraPDF 反向搜索配置：从 PDF 双击跳回编辑器源码","source":[["1-知识/工具/SumatraPDF反向搜索命令行设置"]],"tags":["LaTeX","VSCode","工具"],"categories":["工具"],"permalink":"/pages/b70567"},"headers":[],"relativePath":"工具/SumatraPDF 反向搜索配置：从 PDF 双击跳回编辑器源码.md","filePath":"工具/SumatraPDF 反向搜索配置：从 PDF 双击跳回编辑器源码.md","lastUpdated":1794884251000}'),d={name:"工具/SumatraPDF 反向搜索配置：从 PDF 双击跳回编辑器源码.md"};function s(n,a,i,l,p,u){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="sumatrapdf-反向搜索配置-从-pdf-双击跳回编辑器源码" tabindex="-1">SumatraPDF 反向搜索配置：从 PDF 双击跳回编辑器源码 <a class="header-anchor" href="#sumatrapdf-反向搜索配置-从-pdf-双击跳回编辑器源码" aria-label="Permalink to &quot;SumatraPDF 反向搜索配置：从 PDF 双击跳回编辑器源码&quot;">​</a></h1> <p>用 VSCode（或 Notepad++）编写 LaTeX、用 SumatraPDF 预览 PDF 的组合里，&quot;反向搜索&quot;指在 PDF 里双击任意位置，自动跳转到编辑器中对应位置的源代码（比如跳到某个 tex 文件的对应行）。这个功能需要在 SumatraPDF 的选项里配置一条命令行才能生效。本文给出 VSCode 与 Notepad++ 两种配置，以及一个最常见的失效原因。</p> <h2 id="vscode-配置" tabindex="-1">VSCode 配置 <a class="header-anchor" href="#vscode-配置" aria-label="Permalink to &quot;VSCode 配置&quot;">​</a></h2> <p>打开 SumatraPDF，进入菜单 <strong>设置 → 选项</strong>，在&quot;设置反向搜索命令行&quot;一栏（即双击 PDF 文件时应运行的命令）填入：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;C:\\Program Files\\Microsoft VS Code\\Code.exe&quot; -g &quot;%f:%l&quot;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>%f</code> 会被替换为源文件路径，<code>%l</code> 为行号；</li> <li><code>-g</code> 参数让 VSCode 复用已有窗口打开文件并跳到指定行；</li> <li>VSCode 安装路径不同时相应调整。</li></ul> <p>配置完成后，在 PDF 中双击任意处即可跳到 VSCode 中对应 tex 文件的对应行。</p> <h2 id="notepad-配置" tabindex="-1">Notepad++ 配置 <a class="header-anchor" href="#notepad-配置" aria-label="Permalink to &quot;Notepad++ 配置&quot;">​</a></h2> <p>如果用 Notepad++ 作为编辑器，命令行换成：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;C:\\Program Files (x86)\\Notepad++\\notepad++.exe&quot; -n%l &quot;%f&quot;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>-n%l</code> 指定跳转行号。</p> <h2 id="常见失效原因-作为子进程启动" tabindex="-1">常见失效原因：作为子进程启动 <a class="header-anchor" href="#常见失效原因-作为子进程启动" aria-label="Permalink to &quot;常见失效原因：作为子进程启动&quot;">​</a></h2> <p>一个容易踩的坑：从 VSCode 内部调用 SumatraPDF 时，SumatraPDF 是作为子进程启动的，此时反向搜索可能失败。<strong>先独立运行 SumatraPDF.exe，再进行正反向搜索</strong>，即可避开这个问题。</p> <h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <p>反向搜索只需要一条命令行：VSCode 用 <code>Code.exe -g &quot;%f:%l&quot;</code>，Notepad++ 用 <code>notepad++.exe -n%l &quot;%f&quot;</code>；如果反向搜索不生效，先检查 SumatraPDF 是不是被编辑器当子进程拉起来的，独立启动通常就能解决。</p> <blockquote><p>本文整理自社区分享（<a href="https://blog.csdn.net/liuyukuan/article/details/85239539" target="_blank" rel="noreferrer">CSDN 原文</a>），命令行为事实性配置。</p></blockquote>',29)])])}const h=e(d,[["render",s]]);export{m as __pageData,h as default};
